function beta_cm_fail(string $msg, int $code = 400): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    http_response_code($code); header('Content-Type: application/json');
    echo json_encode(['success' => false, 'error' => $msg]); exit();
}
function beta_cm_out(array $body): never {
    while (ob_get_level() > 0) { ob_end_clean(); }
    header('Content-Type: application/json'); header('Cache-Control: no-store');
    echo json_encode($body); exit();
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $betaOp = (string) ($_POST['action'] ?? '');
    if (!in_array($betaOp, ['delete_video', 'youtube_upload_twitch_vod'], true) || isset($_GET['ajax'])) beta_cm_fail('Unknown action.');
    if (!preg_match('/^\d{1,20}$/', (string) ($_POST['video_id'] ?? ''))) beta_cm_fail(t('videos_error_video_id_required'));
    if (mb_strlen((string) ($_POST['title'] ?? '')) > 300) beta_cm_fail('Unknown action.');
} elseif ($_SERVER['REQUEST_METHOD'] !== 'GET') beta_cm_fail('Unknown action.');
else {
    $betaAjax = (string) ($_GET['ajax'] ?? '');
    if ($betaAjax === 'videos') { if (!in_array((string) ($_GET['tab'] ?? 'videos'), ['videos', 'highlights', 'uploads'], true)) beta_cm_fail('Unknown action.'); }
    elseif ($betaAjax === 'clips') {
        if (!in_array((string) ($_GET['ajax_action'] ?? 'batch'), ['count', 'batch'], true) || !in_array((string) ($_GET['mode'] ?? 'more'), ['more', 'all'], true) || !preg_match('/^\d{0,5}$/', (string) ($_GET['offset'] ?? ''))) beta_cm_fail('Unknown action.');
    } else beta_cm_fail('Unknown action.');
}
// The old card, as fields: the same text and the same YouTube state choice.
function beta_card(array $video, $isClipsMode, array $clipDownloadUrls = [], $youtubeCanUpload = false, array $youtubeTwitchJobs = [], $youtubeComingSoon = false): array {
    $id = (string) ($video['id'] ?? '');
    $thumb = str_replace(['%{width}', '%{height}'], ['320', '180'], (string) ($video['thumbnail_url'] ?? ''));
    $dl = ($isClipsMode && isset($clipDownloadUrls[$id]) && is_array($clipDownloadUrls[$id])) ? $clipDownloadUrls[$id] : [];
    $yt = ['state' => 'none'];
    if (!$isClipsMode && $id !== '') {
        $job = $youtubeTwitchJobs[$id] ?? null;
        $st = is_array($job) ? (string) ($job['status'] ?? '') : '';
        if ($youtubeComingSoon) $yt = ['state' => 'coming_soon', 'label' => t('coming_soon')];
        elseif (!$youtubeCanUpload) $yt = ['state' => 'connect', 'label' => t('videos_connect_youtube')];
        elseif ($st === 'done') $yt = ['state' => 'done', 'label' => t('youtube_status_done')];
        elseif (in_array($st, ['queued', 'pulling', 'uploading'], true)) $yt = ['state' => 'busy', 'label' => t('youtube_status_' . $st)];
        else {
            $lim = youtube_upload_limit_reason(youtube_parse_duration_seconds($video['duration'] ?? null), null);
            $yt = $lim !== null ? ['state' => 'limit', 'label' => t('videos_send_to_youtube'), 'title' => t(youtube_upload_limit_lang_key($lim))]
                : ['state' => 'upload', 'label' => $st === 'failed' ? t('youtube_btn_retry') : t('videos_send_to_youtube')];
        }
    }
    return [
        'id' => $id,
        'title' => isset($video['title']) ? (string) $video['title'] : ($isClipsMode ? t('videos_untitled_clip') : t('videos_untitled_video')),
        'description' => (string) ($video['description'] ?? ''),
        'thumbnail' => preg_match('#^https://#i', $thumb) ? $thumb : '',
        'url' => preg_match('#^https://#i', (string) ($video['url'] ?? '')) ? (string) $video['url'] : '',
        'views' => (int) ($video['view_count'] ?? 0),
        'type' => isset($video['type']) ? (string) $video['type'] : ($isClipsMode ? 'clip' : 'unknown'),
        'duration' => $isClipsMode ? formatClipDuration($video['duration'] ?? null) : formatVideoDuration($video['duration'] ?? ''),
        'date' => $isClipsMode ? formatVideoDate($video['created_at'] ?? '') : formatVideoDate($video['published_at'] ?? ''),
        'creator' => (string) ($video['creator_name'] ?? ''),
        'broadcaster' => (string) ($video['broadcaster_name'] ?? ''),
        'featured' => !empty($video['is_featured']),
        'vod_offset' => isset($video['vod_offset']) && $video['vod_offset'] !== null ? (int) $video['vod_offset'] : null,
        'landscape' => preg_match('#^https://#i', (string) ($dl['landscape_download_url'] ?? '')) ? (string) $dl['landscape_download_url'] : '',
        'portrait' => preg_match('#^https://#i', (string) ($dl['portrait_download_url'] ?? '')) ? (string) $dl['portrait_download_url'] : '',
        'youtube' => $yt,
    ];
}
if (isset($_GET['ajax']) && $_GET['ajax'] === 'clips') {
	header('Content-Type: application/json; charset=utf-8');
	if ($channelUserId === '' || $accessToken === '') {
		echo json_encode([
			'success' => false,
			'message' => t('videos_error_no_channel_id'),
		]);
		exit();
	}
	$ajaxAction = isset($_GET['ajax_action']) ? trim((string) $_GET['ajax_action']) : 'batch';
	if ($ajaxAction === 'count') {
		$countResult = countChannelClips($channelUserId, $accessToken, $clientID, 1000);
		echo json_encode([
			'success' => $countResult['error'] === '',
			'total_count' => $countResult['count'],
			'capped' => $countResult['capped'],
			'message' => $countResult['error'],
		]);
		exit();
	}
	$offset = isset($_GET['offset']) ? max(0, (int) $_GET['offset']) : 0;
	$loadMode = isset($_GET['mode']) ? trim((string) $_GET['mode']) : 'more';
	$loadAll = $loadMode === 'all';
	$loadedItems = [];
	$error = '';
	$sortedClipsResult = fetchSortedChannelClips($channelUserId, $accessToken, $clientID, 1000);
	$loadedItems = [];
	$totalClips = 0;
	$nextOffset = $offset;
	$hasMore = false;
	if ($sortedClipsResult['error'] !== '') {
		$error = $sortedClipsResult['error'];
	} else {
		$allClips = $sortedClipsResult['items'];
		$totalClips = count($allClips);
		$limit = $loadAll ? max(0, $totalClips - $offset) : 20;
		$loadedItems = array_slice($allClips, $offset, $limit);
		$nextOffset = $offset + count($loadedItems);
		$hasMore = $nextOffset < $totalClips;
	}
	$clipIds = [];
	foreach ($loadedItems as $clip) {
		if (isset($clip['id']) && (string) $clip['id'] !== '') {
			$clipIds[] = (string) $clip['id'];
		}
	}
	$downloadLookup = fetchClipDownloadUrls($clipIds, $channelUserId, $editorUserId, $accessToken, $clientID);
	if ($downloadLookup['error'] !== '' && $error === '') {
		$error = $downloadLookup['error'];
	}
	sortClipsByCreatedDate($loadedItems);
	$html = '';
	foreach ($loadedItems as $clip) {
		$betaCards[] = beta_card($clip, true, $downloadLookup['downloads']);
	}
	echo json_encode([
		'success' => $error === '',
		'cards' => $betaCards ?? [],
		'next_offset' => $nextOffset,
		'has_more' => $hasMore,
		'total_count' => $totalClips,
		'loaded_count' => count($loadedItems),
		'message' => $error,
	]);
	exit();
}

// AJAX shell for archive / highlights / uploads (Helix deferred from first paint)
if (isset($_GET['ajax']) && $_GET['ajax'] === 'videos') {
	header('Content-Type: application/json; charset=utf-8');
	if ($channelUserId === '' || $accessToken === '') {
		echo json_encode([
			'success' => false,
			'message' => t('videos_error_no_channel_id'),
			'html' => '',
			'count' => 0,
		]);
		exit();
	}
	$ajaxTab = isset($_GET['tab']) ? trim((string) $_GET['tab']) : 'videos';
	if (!in_array($ajaxTab, ['videos', 'highlights', 'uploads'], true)) {
		$ajaxTab = 'videos';
	}
	$videoTypeMapAjax = [
		'videos'     => 'archive',
		'highlights' => 'highlight',
		'uploads'    => 'upload',
	];
	$videoTypeFilter = $videoTypeMapAjax[$ajaxTab] ?? 'archive';
	$allVideos = fetchAllTwitchItems('videos', [
		'user_id' => $channelUserId,
		'first'   => 100,
		'type'    => $videoTypeFilter,
	], $accessToken, $clientID, 1000);
	$html = '';
	foreach ($allVideos['items'] as $video) {
		$betaCards[] = beta_card($video, false, [], $youtubeCanUpload, $youtubeTwitchJobs, !$youtubeAdminTesting);
	}
	echo json_encode([
		'success' => $allVideos['error'] === '',
		'cards' => $betaCards ?? [],
		'count' => count($allVideos['items']),
		'message' => $allVideos['error'],
	]);
	exit();
}

$flashSuccess = '';
$flashError = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action']) && $_POST['action'] === 'youtube_upload_twitch_vod') {
	header('Content-Type: application/json; charset=utf-8');
	$vodId = isset($_POST['video_id']) ? trim((string) $_POST['video_id']) : '';
	$vodTitle = isset($_POST['title']) ? trim((string) $_POST['title']) : '';
	if (!youtube_admin_testing()) {
		echo json_encode(['ok' => false, 'error' => t('coming_soon')]);
		exit();
	}
	if (!youtube_twitch_video_id_ok($vodId) || $channelUserId === '' || $accessToken === '') {
		echo json_encode(['ok' => false, 'error' => t('videos_error_video_id_required')]);
		exit();
	}
	$owned = fetchTwitchPage('videos', ['id' => [$vodId]], $accessToken, $clientID);
	$ownedItem = $owned['items'][0] ?? null;
	$ownedUser = is_array($ownedItem) ? (string) ($ownedItem['user_id'] ?? '') : '';
	$ownedType = is_array($ownedItem) ? (string) ($ownedItem['type'] ?? '') : '';
	if ($owned['error'] !== '' || $ownedUser !== $channelUserId) {
		echo json_encode(['ok' => false, 'error' => t('videos_youtube_not_your_vod')]);
		exit();
	}
	if (!in_array($ownedType, ['archive', 'highlight'], true)) {
		echo json_encode(['ok' => false, 'error' => t('videos_youtube_type_unsupported')]);
		exit();
	}
	if ($vodTitle === '' && !empty($ownedItem['title'])) {
		$vodTitle = (string) $ownedItem['title'];
	}
	$durationSeconds = youtube_parse_duration_seconds($ownedItem['duration'] ?? null);
	$limit = youtube_upload_limit_reason($durationSeconds, null);
	if ($limit !== null) {
		echo json_encode(['ok' => false, 'error' => t(youtube_upload_limit_lang_key($limit))]);
		exit();
	}
	$queued = youtube_enqueue_twitch_vod($conn, (int) ($user_id ?? 0), $vodId, $vodTitle, null, $durationSeconds, null);
	if (!empty($queued['ok'])) {
		$msg = t('youtube_upload_queued');
		if (!empty($queued['already']) && ($queued['status'] ?? '') === 'done') {
			$msg = t('youtube_upload_already_done');
		} elseif (!empty($queued['already'])) {
			$msg = t('youtube_upload_already_queued');
		}
		echo json_encode([
			'ok' => true,
			'status' => $queued['status'] ?? 'queued',
			'youtube_video_id' => $queued['youtube_video_id'] ?? '',
			'message' => $msg,
		]);
		exit();
	}
	$err = (string) ($queued['error'] ?? '');
	$map = [
		'not_linked' => t('youtube_upload_not_linked'),
		'no_upload_scope' => t('youtube_upload_no_scope'),
		'bad_video' => t('videos_error_video_id_required'),
		'not_ready' => t('youtube_upload_not_ready'),
		'db' => t('youtube_upload_failed'),
		'too_long' => t('youtube_upload_too_long'),
		'too_large' => t('youtube_upload_too_large'),
	];
	echo json_encode(['ok' => false, 'error' => $map[$err] ?? t('youtube_upload_failed')]);
	exit();
}

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['action']) && $_POST['action'] === 'delete_video') {
	$deleteVideoId = isset($_POST['video_id']) ? trim((string) $_POST['video_id']) : '';
	if ($deleteVideoId === '') {
		$flashError = t('videos_error_video_id_required');
	} else {
		$deleteUrl = 'https://api.twitch.tv/helix/videos?' . buildTwitchQuery(['id' => [$deleteVideoId]]);
		$deleteResult = twitchApiRequest('DELETE', $deleteUrl, $accessToken, $clientID);
		$deleteBody = json_decode((string) $deleteResult['body'], true);
		if ($deleteResult['curl_error']) {
			error_log('videos.php: deleteResult: ' . $deleteResult['curl_error']);
			$flashError = t('videos_error_delete_failed') . ' ' . t('videos_js_try_again');
		} elseif ((int) $deleteResult['http_code'] === 200) {
			$deletedItems = isset($deleteBody['data']) && is_array($deleteBody['data']) ? $deleteBody['data'] : [];
			if (in_array($deleteVideoId, $deletedItems, true) || empty($deletedItems)) {
				$flashSuccess = t('videos_deleted_success');
			} else {
				$flashSuccess = t('videos_delete_completed');
			}
		} else {
			$apiMessage = is_array($deleteBody) && isset($deleteBody['message']) ? (string) $deleteBody['message'] : '';
			$flashError = t('videos_error_delete_failed_http', ['code' => (int) $deleteResult['http_code']]) . ($apiMessage !== '' ? ' ' . $apiMessage : '');
		}
	}
}


if (($_POST['action'] ?? '') !== 'delete_video') beta_cm_fail('Unknown action.');
beta_cm_out(['success' => $flashError === '', 'message' => $flashSuccess, 'error' => $flashError ?: null]);
